  'gov.board-empty': { class: 'root-prose', text: 'The board is empty. Recruiting at least three credentialed clinician reviewers is in progress and has not completed. Until it does, nothing in this build is signed, no scenario is described as reviewed, and the release gate refuses to publish.' },
  'gov.member': { class: 'root-prose', text: ', {credential}, {institution}. Reviews: {scope}. Joined {joined}. Competing interests: {interests}.' },
